```javascript
const grid = document.getElementById('grid');
const scoreBot1 = document.getElementById('score-bot1');
const scoreBot2 = document.getElementById('score-bot2');
const foodIntervalInput = document.getElementById('food-interval');
const bot1SightDistanceInput = document.getElementById('bot1-sight-distance');
const bot2SightDistanceInput = document.getElementById('bot2-sight-distance');

const gridSize = 10;
const moveInterval = 500; // Milliseconds between bot movements

let bot1 = { x: 0, y: 0, dx: 0, dy: 0, score: 0 };
let bot2 = { x: 9, y: 9, dx: 0, dy: 0, score: 0 };

// Initialize Grid
for (let i = 0; i < gridSize * gridSize; i++) {
    const cell = document.createElement('div');
    cell.classList.add('cell');
    grid.appendChild(cell);
}

function getCell(x, y) {
    return grid.children[y * gridSize + x];
}

function spawnFood() {
    // Clear existing food
    for (let i = 0; i < grid.children.length; i++) {
        grid.children[i].classList.remove('food');
    }

    // Spawn new food at random location
    let x, y;
    do {
        x = Math.floor(Math.random() * gridSize);
        y = Math.floor(Math.random() * gridSize);
    } while ((x === bot1.x && y === bot1.y) || (x === bot2.x && y === bot2.y));

    getCell(x, y).classList.add('food');
}

function findClosestFood(bot, sightDistance) {
    let closestFood = null;
    let minDistance = Infinity;

    for (let i = 0; i < grid.children.length; i++) {
        const cell = grid.children[i];
        if (cell.classList.contains('food')) {
            const foodX = i % gridSize;
            const foodY = Math.floor(i / gridSize);
            const distance = Math.abs(bot.x - foodX) + Math.abs(bot.y - foodY);

            if (distance < minDistance && distance <= sightDistance) {
                minDistance = distance;
                closestFood = { x: foodX, y: foodY };
            }
        }
    }

    return closestFood;
}

function moveSmartBot(bot, sightDistance) {
    const closestFood = findClosestFood(bot, sightDistance);

    if (closestFood) {
        bot.dx = Math.sign(closestFood.x - bot.x);
        bot.dy = Math.sign(closestFood.y - bot.y);
    } else {
        // If no food in sight, move randomly
        bot.dx = Math.floor(Math.random() * 3) - 1;
        bot.dy = Math.floor(Math.random() * 3) - 1;
    }
}

function moveBot(bot, sightDistanceInput) {
    if (sightDistanceInput) {
        moveSmartBot(bot, parseInt(sightDistanceInput.value));
    }

    // Update position
    bot.x = Math.max(0, Math.min(gridSize - 1, bot.x + bot.dx));
    bot.y = Math.max(0, Math.min(gridSize - 1, bot.y + bot.dy));
}

function updateBot(bot, className) {
    // Remove old bot position
    for (let i = 0; i < grid.children.length; i++) {
        grid.children[i].classList.remove(className);
    }

    // Add new bot position
    const cell = getCell(bot.x, bot.y);
    cell.classList.add(className);

    // Check if bot eats food
    if (cell.classList.contains('food')) {
        cell.classList.remove('food');
        bot.score++;
    }
}

function updateScores() {
    scoreBot1.textContent = bot1.score;
    scoreBot2.textContent = bot2.score;
}

function botMovementLoop() {
    moveBot(bot1, bot1SightDistanceInput); // Make bot1 smart
    moveBot(bot2, bot2SightDistanceInput); // Make bot2 smart
    updateBot(bot1, 'bot1');
    updateBot(bot2, 'bot2');
    updateScores();
    setTimeout(botMovementLoop, moveInterval);
}

// Food apparition loop
function foodLoop() {
    spawnFood();
    const intervalSeconds = parseInt(foodIntervalInput.value) * 1000;
    setTimeout(foodLoop, intervalSeconds);
}

// UI Updaters
foodIntervalInput.addEventListener('input', () => {
    document.getElementById('food-interval-value').textContent = foodIntervalInput.value;
});
bot1SightDistanceInput.addEventListener('input', () => {
    document.getElementById('bot1-sight-value').textContent = bot1SightDistanceInput.value;
});
bot2SightDistanceInput.addEventListener('input', () => {
    document.getElementById('bot2-sight-value').textContent = bot2SightDistanceInput.value;
});

// Start the game
updateBot(bot1, 'bot1');
updateBot(bot2, 'bot2');
spawnFood();
botMovementLoop();
foodLoop();
```

