    const { employeeId, startDate, endDate } = req.body;

    try {
        // Insert the complimentary leave information into the database
        const [result] = await db.promise().query(
            'INSERT INTO ComplimentaryLeaves (employee_id, start_date, end_date) VALUES (?, ?, ?)',
