### 2. The React Frontend
In React, you will use the `useEffect` hook to fetch the data when the component mounts, and the `useState` hook to store the data and bind it to your form inputs.

**React Component (`UserProfileForm.jsx`):**
```jsx
import React, { useState, useEffect } from 'react';

const UserProfileForm = ({ userId }) => {
  // 1. Set up state for your form fields
  const [formData, setFormData] = useState({
    first_name: '',
    last_name: '',
    email: '',
    phone_number: ''
  });

  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);

  // 2. Fetch the data when the component loads or userId changes
  useEffect(() => {
    const fetchUserData = async () => {
      try {
        const response = await fetch(`/api/users/${userId}`);

        if (!response.ok) {
          throw new Error('Failed to fetch user data');
        }

        const data = await response.json();

        // 3. Auto-populate the state with the fetched data
        setFormData({
          first_name: data.first_name || '',
          last_name: data.last_name || '',
          email: data.email || '',
          phone_number: data.phone_number || ''
        });
      } catch (err) {
        setError(err.message);
      } finally {
        setIsLoading(false);
      }
    };

    fetchUserData();
  }, [userId]); // Dependency array ensures this runs if userId changes

  // 4. Handle user typing in the fields after they are populated
  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prevData) => ({
      ...prevData,
      [name]: value
    }));
  };

  if (isLoading) return <div>Loading data...</div>;
  if (error) return <div>Error: {error}</div>;

  // 5. Bind the state to the input values
  return (
    <form>
      <div>
        <label>First Name:</label>
        <input
          type="text"
          name="first_name"
          value={formData.first_name}
          onChange={handleChange}
        />
      </div>

      <div>
        <label>Last Name:</label>
        <input
          type="text"
          name="last_name"
          value={formData.last_name}
          onChange={handleChange}
        />
      </div>

      <div>
        <label>Email:</label>
        <input
          type="email"
          name="email"
          value={formData.email}
          onChange={handleChange}
        />
      </div>

      <div>
        <label>Phone Number:</label>
        <input
          type="tel"
          name="phone_number"
          value={formData.phone_number}
          onChange={handleChange}
        />
      </div>

      <button type="submit">Save</button>
    </form>
  );
};

export default UserProfileForm;
```

### Alternative Scenario: Auto-populating based on a user action
If you want to auto-populate fields *after* a user does something (like typing in a Zip Code to auto-fill City and State), you would move the `fetch` call out of `useEffect` and put it into an `onBlur` or `onChange` handler attached to the specific input field.

